import * as pdfjsLib from 'pdfjs-dist';

// Set the workerSrc globally to avoid issues with the PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

const parsePDF = async (file) => {
  const reader = new FileReader();
  reader.readAsArrayBuffer(file);

  return new Promise((resolve, reject) => {
    reader.onload = async function () {
      const typedArray = new Uint8Array(reader.result);
      const pdf = await pdfjsLib.getDocument(typedArray).promise;

      let parsedText = '';

      // Loop through all the pages
      for (let i = 0; i < pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        const textContent = await page.getTextContent();

        // Extract text from each page
        const pageText = textContent.items.map((item) => item.str).join(' ');
        parsedText += pageText + '\n';
      }

      // Once text is parsed, organize into specific sections
      const organizedData = scrapeResumeDetails(parsedText);
      resolve(organizedData);
    };

    reader.onerror = function (error) {
      reject(error);
    };
  });
};

// Function to scrape specific details (name, experience, projects, and skills)
const scrapeResumeDetails = (parsedText) => {
  const details = {};

  // Extract Name (assume the first line or two contains the name)
  const nameMatch = parsedText.match(/^(.*?)(\n|$)/);
  details.name = nameMatch ? nameMatch[1].trim() : 'N/A';

  // Extract Experience section using regex pattern
  const experienceMatch = parsedText.match(/EXPERIENCE\s*(.*?)\s*(?=(PROJECTS|SKILLS|$))/s);
  details.experience = experienceMatch ? experienceMatch[1].trim() : 'N/A';

  // Extract Projects section using regex pattern
  const projectsMatch = parsedText.match(/PROJECTS\s*(.*?)\s*(?=(EXPERIENCE|SKILLS|$))/s);
  details.projects = projectsMatch ? projectsMatch[1].trim() : 'N/A';

  // Extract Skills section using regex pattern
  const skillsMatch = parsedText.match(/SKILLS\s*(.*)/s);
  details.skills = skillsMatch ? skillsMatch[1].trim() : 'N/A';

  return details;
};

export { parsePDF };
